import sys,re,glob,os
sys.path.insert(0,'.')
from load import *
from dump2 import strip_heredoc
from meta import *
LIBN=r'AnyType|CompilerBuiltin|CompilerLibrary|CompilerAlgebra|CompilerSystem'
SRC=r'(ProjectFortress/src|/Library/|LibraryBuiltin/|build\.xml|/astgen/|\.scala|\.java)'
def flags(c):
    cmd=c['input'].get('command','') if c['name']=='Bash' else ''
    s=strip_heredoc(cmd)
    nl=[l for l in s.split('\n') if not re.match(r'\s*(grep|egrep|jq|echo|printf|sed -n|head|tail|cat\b|ls\b|awk|rg|wc|git (log|commit|show|diff)|T=|D=|#)',l)]
    t='\n'.join(nl)
    f=[]
    if re.search(r'\bant\s+(-\S+\s+)*(compileAll|compile)\b',t): f.append('ANT')
    elif re.search(r'\bant\s+(-\S+\s+)*(compileAll|compile)\b',cmd): f.append('ant?')
    if re.search(r'fortress\s+compile',t) and re.search(LIBN,cmd): f.append('LIB')
    if re.search(r'seed-worktree|git (-C \S+ )?worktree add',t): f.append('SEED')
    if re.search(r'git (-C \S+ )?(checkout|stash|merge|cherry-pick|reset|apply|rebase|pull|am)\b',t) : f.append('GIT')
    if re.search(r'git (-C \S+ )?commit',t): f.append('COMMIT')
    if re.search(r'(sed -i|perl -pi|patch\b)',t) and re.search(SRC,t): f.append('SEDI')
    if re.search(r'wait_for|until grep|tail -f',cmd): f.append('WAIT')
    if re.search(r'gate|testFast|testSystem',t): pass
    return f
def timeline(path,lab=''):
    a=load_agent(path)
    out=[]
    for c in a['calls']:
        r=a['results'].get(c['id'])
        d=round(r[0]-c['ts']) if r else None
        if c['name'] in ('Edit','Write','NotebookEdit'):
            fp=c['input'].get('file_path','')
            if re.search(SRC,fp):
                out.append((c['ts'],'EDIT',d,fp.replace('/home/user/','')[:110]))
            continue
        if c['name']!='Bash': continue
        f=flags(c)
        if f:
            cmd=' '.join(strip_heredoc(c['input'].get('command','')).split())
            res=''
            if r:
                m=re.findall(r'(BUILD (?:SUCCESSFUL|FAILED)|Total time: [^\n]*|EXIT=\d+)',r[1])
                res=' ['+';'.join(m[:3])+']' if m else ''
